  def rlx_trainer_free(_h), do: :erlang.nif_error(:not_loaded)
  def rlx_tokenizer_free(_h), do: :erlang.nif_error(:not_loaded)
  def rlx_sampler_free(_h), do: :erlang.nif_error(:not_loaded)
  def rlx_group_free(_h), do: :erlang.nif_error(:not_loaded)
  def rlx_model_free(_h), do: :erlang.nif_error(:not_loaded)
  def support_optimizer_step(_h, _names, _params, _grads), do: :erlang.nif_error(:not_loaded)
end

defmodule Rlx do
  @moduledoc "rlx for Elixir: free functions; a module per class (`Rlx.Graph`, `Rlx.Session`, …)."
  alias Rlx.Support, as: S

  @doc "\"No node\", for an optional node argument."
  def none, do: S.none()

  @doc """
  The library version, e.g. "0.2.18".
  """
  def version() do
    S.unwrap(Rlx.Native.rlx_version())
  end

  @doc """
  Backends compiled in and usable on this machine.
  """
  def devices() do
    S.decode(S.unwrap(Rlx.Native.rlx_devices()))
  end

  @doc """
  Whether a backend is compiled in and has hardware.
  """
  def is_available(name) do
    S.unwrap(Rlx.Native.rlx_is_available(name))
  end

  @doc """
  The canonical label of a device name; errors on an unknown one.
  """
  def parse_device(name) do
    (S.unwrap(Rlx.Native.rlx_parse_device(name)) || "")
  end

  @doc """
  Every backend rlx knows, with whether this build and machine have it.
  """
  def backends_manifest() do
    S.decode(S.unwrap(Rlx.Native.rlx_backends_manifest()))
  end

  @doc """
  The fastest device that runs every op of `graph`.
  """
  def fastest_device_for(graph, opts \\ []) do
    o = S.opts(opts, [policy: nil])
    (S.unwrap(Rlx.Native.rlx_fastest_device_for(graph, S.json_or_nil(o.policy))) || "")
  end

  @doc """
  Every device's verdict on `graph`: available, supports it, why not.
  """
  def device_report(graph, opts \\ []) do
    o = S.opts(opts, [policy: nil])
    S.decode(S.unwrap(Rlx.Native.rlx_device_report(graph, S.json_or_nil(o.policy))))
  end

  @doc """
  Static analysis of `graph` across backends: unsupported ops, numerics, cost.
  """
  def check(graph, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.decode(S.unwrap(Rlx.Native.rlx_check(graph, S.json_or_nil(o.options))))
  end

  @doc """
  The backends `check` can analyse.
  """
  def check_backends() do
    S.decode(S.unwrap(Rlx.Native.rlx_check_backends()))
  end

  @doc """
  A graph whose outputs are [loss, …d(loss)/d(wrt)], with a `d_output` seed input.
  """
  def grad(graph, wrt) do
    S.unwrap(Rlx.Native.rlx_grad(graph, wrt, length(wrt)))
  end

  @doc """
  Forward mode: [...primals, ...tangents], one `tangent_<name>` input per seeded node.
  """
  def jvp(graph, tangent_for) do
    S.unwrap(Rlx.Native.rlx_jvp(graph, tangent_for, length(tangent_for)))
  end

  @doc """
  Hessian-vector product, forward-over-reverse.
  """
  def hvp(graph, wrt) do
    S.unwrap(Rlx.Native.rlx_hvp(graph, wrt, length(wrt)))
  end

  @doc """
  Batch the named inputs along a new leading axis.
  """
  def vmap(graph, names, batch_size) do
    S.unwrap(Rlx.Native.rlx_vmap(graph, names, length(names), batch_size))
  end

  @doc """
  The order-th derivative of a scalar function w.r.t. scalar input `wrt`.
  """
  def nth_order_grad(graph, wrt, order) do
    S.unwrap(Rlx.Native.rlx_nth_order_grad(graph, wrt, order))
  end

  @doc """
  The order-th derivative contracted against one direction per level (`dir_0`, …).
  """
  def directional_nth_grad(graph, wrt, order) do
    S.unwrap(Rlx.Native.rlx_directional_nth_grad(graph, wrt, order))
  end

  @doc """
  Export an INT8 (or legalizable f32) graph as SystemVerilog under `out_dir`; returns the files written.
  """
  def export_fpga(graph, out_dir, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.decode(S.unwrap(Rlx.Native.rlx_export_fpga(graph, out_dir, S.json_or_nil(o.options))))
  end

  @doc """
  Copy `source` into `target` (both borrowed; `target` grows) and return
  `source`'s outputs as `target` nodes. options: {bind: {leaf name: node},
  prefix, adapt_shapes}. Unbound same-named leaves are shared (a tied weight)
  unless `prefix` keeps them apart. On error `target` is unchanged.
  """
  def splice(target, source, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.unwrap(Rlx.Native.rlx_splice(target, source, S.json_or_nil(o.options)))
  end

  @doc """
  `a` and `b` side by side: a's outputs, then b's; same-named leaves shared.
  """
  def parallel(a, b, opts \\ []) do
    o = S.opts(opts, [name: nil])
    S.unwrap(Rlx.Native.rlx_parallel(a, b, o.name))
  end

  @doc """
  `b` after `a`: b's inputs, in creation order, are fed by a's outputs.
  """
  def sequential(a, b, opts \\ []) do
    o = S.opts(opts, [name: nil])
    S.unwrap(Rlx.Native.rlx_sequential(a, b, o.name))
  end

  @doc """
  The subgraph computing `outputs`, with them as its outputs.
  """
  def extract(graph, outputs) do
    S.unwrap(Rlx.Native.rlx_extract(graph, outputs, length(outputs)))
  end

  @doc """
  Quantize f32 values to a GGUF dtype's bytes.
  """
  def quantize(data, dtype) do
    S.unwrap(Rlx.Native.rlx_quantize(data, length(data), dtype))
  end

  @doc """
  Dequantize GGUF bytes of `dtype` to f32 (`count` trims padding).
  """
  def dequantize(data, dtype, opts \\ []) do
    o = S.opts(opts, [count: nil])
    S.unwrap(Rlx.Native.rlx_dequantize(data, byte_size(data), dtype, S.box(o.count)))
  end

  @doc """
  safetensors (or PyTorch / ONNX) → GGUF, quantized to `scheme` by default.
  options: {architecture, overrides: {tensor: scheme}, skip_norm_bias}. Returns
  {tensors, input_bytes, output_bytes, compression_ratio, output_path, schemes}.
  """
  def convert_to_gguf(src, dst, opts \\ []) do
    o = S.opts(opts, [scheme: "Q4_K", options: nil])
    S.decode(S.unwrap(Rlx.Native.rlx_convert_to_gguf(src, dst, o.scheme, S.json_or_nil(o.options))))
  end

  @doc """
  Load every tensor of a weights file as f32: format "mlx" | "dduf" | "nemo" | "pt" | "safetensors".
  """
  def load_weights(format, path) do
    S.unwrap(Rlx.Native.rlx_load_weights(format, path))
  end

  @doc """
  Open an .rlxp package: its manifest as JSON.
  """
  def open_rlxp(path) do
    S.decode(S.unwrap(Rlx.Native.rlx_rlxp_open(path)))
  end

  @doc """
  Check an .rlxp package's hashes and layout.
  """
  def verify_rlxp(path) do
    S.decode(S.unwrap(Rlx.Native.rlx_rlxp_verify(path)))
  end

  @doc """
  Convert a model (from "gguf" | "mlx" | "dduf" | "nemo" | "pt") into an .rlxp package.
  """
  def to_rlxp(from, src, dst, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.unwrap(Rlx.Native.rlx_to_rlxp(from, src, dst, S.json_or_nil(o.options)))
    :ok
  end

  @doc """
  The most likely token.
  """
  def argmax(logits) do
    S.unwrap(Rlx.Native.rlx_argmax(logits, length(logits)))
  end

  @doc """
  Sample one token: options {temperature, top_k, top_p, min_p, repetition_penalty, seed}.
  """
  def sample_next(logits, opts \\ []) do
    o = S.opts(opts, [history: [], options: nil])
    S.unwrap(Rlx.Native.rlx_sample_next(logits, length(logits), o.history, length(o.history), S.json_or_nil(o.options)))
  end

  @doc """
  Render chat `messages` [{role, content}] with a Jinja chat template.
  """
  def render_chat(template, messages, opts \\ []) do
    o = S.opts(opts, [add_generation_prompt: true])
    (S.unwrap(Rlx.Native.rlx_render_chat(template, S.json(messages), o.add_generation_prompt)) || "")
  end

  @doc """
  `world` free loopback addresses ("127.0.0.1:port"), for running every rank on one machine.
  """
  def loopback_peers(world) do
    S.decode(S.unwrap(Rlx.Native.rlx_loopback_peers(world)))
  end

  @doc """
  Every model provider: [{name, description, tasks, families}] — the built-in
  `rlxp` and every plugin loaded (RLX_MODEL_PLUGINS or load_model_plugin).
  """
  def model_providers() do
    S.decode(S.unwrap(Rlx.Native.rlx_model_providers()))
  end

  @doc """
  Load a model plugin library; returns its providers' names.
  """
  def load_model_plugin(path) do
    S.decode(S.unwrap(Rlx.Native.rlx_load_model_plugin(path)))
  end

  @doc """
  Write `graph` (borrowed) and its f32 `weights` as an .rlxp model package
  that `Model.open` runs on any device. model: {task, family, outputs: [names], metadata}.
  """
  def save_model(graph, path, weights, opts \\ []) do
    o = S.opts(opts, [model: nil])
    in_weights = S.inputs(weights)
    S.unwrap(Rlx.Native.rlx_save_model(graph, path, in_weights.names, in_weights.data, in_weights.lens, length(in_weights.names), S.json_or_nil(o.model)))
    :ok
  end
end

defmodule Rlx.Graph do
  @moduledoc """
  A graph under construction. Its builders (`matmul`, `conv2d`, …) are the op
  table's (`table.rs`); these rows are its lifecycle.
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_graph_free(this)

  def new(opts \\ []) do
    o = S.opts(opts, [name: "graph"])
    S.unwrap(Rlx.Native.rlx_graph_new(o.name))
  end

  @doc """
  A deep copy — compile one, keep building on the other.
  """
  def clone(this) do
    S.unwrap(Rlx.Native.rlx_graph_clone(this))
  end

  @doc """
  Whether a compile (or a body-graph argument) consumed it.
  """
  def is_consumed(this) do
    S.unwrap(Rlx.Native.rlx_graph_is_consumed(this))
  end

  @doc """
  A runtime input. `dtype` defaults to f32.
  """
  def input(this, name, shape, opts \\ []) do
    o = S.opts(opts, [dtype: "f32"])
    S.unwrap(Rlx.Native.rlx_graph_input(this, name, shape, length(shape), o.dtype))
  end

  @doc """
  A trainable / loadable weight, filled by `set_params` at run time.
  """
  def param(this, name, shape, opts \\ []) do
    o = S.opts(opts, [dtype: "f32"])
    S.unwrap(Rlx.Native.rlx_graph_param(this, name, shape, length(shape), o.dtype))
  end

  @doc """
  A rank-0 literal that broadcasts in binary ops.
  """
  def constant(this, value, opts \\ []) do
    o = S.opts(opts, [dtype: "f32"])
    S.unwrap(Rlx.Native.rlx_graph_constant(this, value, o.dtype))
  end

  @doc """
  A constant tensor of zeros.
  """
  def zeros(this, dims, opts \\ []) do
    o = S.opts(opts, [dtype: "f32"])
    S.unwrap(Rlx.Native.rlx_graph_zeros(this, dims, length(dims), o.dtype))
  end

  @doc """
  A constant tensor filled with `value`.
  """
  def full(this, dims, value, opts \\ []) do
    o = S.opts(opts, [dtype: "f32"])
    S.unwrap(Rlx.Native.rlx_graph_full(this, dims, length(dims), value, o.dtype))
  end

  @doc """
  Mark the graph's outputs, in order.
  """
  def set_outputs(this, outputs) do
    S.unwrap(Rlx.Native.rlx_graph_set_outputs(this, outputs, length(outputs)))
    :ok
  end

  @doc """
  The output node ids, in order.
  """
  def outputs(this) do
    S.unwrap(Rlx.Native.rlx_graph_outputs(this))
  end

  @doc """
  Name output `index`, so a compiled graph finds it by name.
  """
  def name_output(this, index, name) do
    S.unwrap(Rlx.Native.rlx_graph_name_output(this, index, name))
    :ok
  end

  @doc """
  Each output's name, in order; "" for an unnamed one.
  """
  def output_names(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_graph_output_names(this)))
  end

  @doc """
  `(dims, dtype)` of a node; a dynamic dim reads back as `-1`.
  """
  def shape_of(this, id) do
    S.decode(S.unwrap(Rlx.Native.rlx_graph_shape_of(this, id)))
  end

  def node_count(this) do
    S.unwrap(Rlx.Native.rlx_graph_node_count(this))
  end

  def name(this) do
    (S.unwrap(Rlx.Native.rlx_graph_name(this)) || "")
  end

  @doc """
  Every `Param` name, in creation order — what `set_params` must cover.
  """
  def param_names(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_graph_param_names(this)))
  end

  @doc """
  Distinct op kinds present, sorted.
  """
  def op_kinds(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_graph_op_kinds(this)))
  end

  @doc """
  Shape-inferred matmul.
  """
  def matmul(this, lhs, rhs) do
    S.unwrap(Rlx.Native.rlx_graph_matmul(this, lhs, rhs))
  end

  @doc """
  Matmul with an explicit output shape, for a layout inference would not pick.
  """
  def matmul_with_shape(this, lhs, rhs, out_shape, opts \\ []) do
    o = S.opts(opts, [dtype: "f32"])
    S.unwrap(Rlx.Native.rlx_graph_matmul_with_shape(this, lhs, rhs, out_shape, length(out_shape), o.dtype))
  end

  @doc """
  `x = A⁻¹·b`; `x` takes `b`'s shape unless `out_shape` is given.
