    o = S.opts(opts, [out_shape: nil, dtype: "f32"])
    S.unwrap(Rlx.Native.rlx_graph_batched_dense_solve(this, a, b, (o.out_shape || []), length(o.out_shape || []), o.dtype))
  end

  def cholesky(this, a) do
    S.unwrap(Rlx.Native.rlx_graph_cholesky(this, a))
