  def gelu_approx(this, x) do
    S.unwrap(Rlx.Native.rlx_graph_gelu_approx(this, x))
  end

  def silu(this, x) do
    S.unwrap(Rlx.Native.rlx_graph_silu(this, x))
  end

  def relu(this, x) do
    S.unwrap(Rlx.Native.rlx_graph_relu(this, x))
  end

