defmodule Rlx.Partition do
  @moduledoc """
  A graph split into self-contained parts that run in order: part i reads
  its `imports` from earlier parts' `exports` of the same name.
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_partition_free(this)

  @doc """
  Node i goes to part assign[i] (`node_count()` entries; inputs', params'
  and constants' are ignored). Every edge must run to the same or a later part.
  """
  def new(graph, assign) do
    S.unwrap(Rlx.Native.rlx_partition_new(graph, assign, length(assign)))
  end

  @doc """
  Two parts: `cut` and everything it reads, then the rest.
  """
  def split_at(graph, cut) do
    S.unwrap(Rlx.Native.rlx_partition_split_at(graph, cut, length(cut)))
  end

  @doc """
  One part per independent subgraph; the parts import nothing.
  """
  def components(graph) do
    S.unwrap(Rlx.Native.rlx_partition_components(graph))
  end

  @doc """
  The number of parts.
  """
  def num_parts(this) do
    S.unwrap(Rlx.Native.rlx_partition_num_parts(this))
  end

  @doc """
  A copy of one part's graph.
  """
  def graph(this, part) do
    S.unwrap(Rlx.Native.rlx_partition_graph(this, part))
  end

  @doc """
  The boundary names a part reads.
  """
  def imports(this, part) do
    S.decode(S.unwrap(Rlx.Native.rlx_partition_imports(this, part)))
  end

  @doc """
  The name of each of a part's outputs.
  """
  def exports(this, part) do
    S.decode(S.unwrap(Rlx.Native.rlx_partition_exports(this, part)))
  end

  @doc """
  Where each source output went: [[part, output index], …].
  """
  def outputs(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_partition_outputs(this)))
  end

  @doc """
  The parts as one graph again.
  """
  def merge(this) do
    S.unwrap(Rlx.Native.rlx_partition_merge(this))
  end
end

defmodule Rlx.Session do
  @moduledoc """
  A device and precision to compile graphs for.
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_session_free(this)

  @doc """
  `policy` is a preset name ("mixed") or {op kind: dtype}.
  """
  def new(opts \\ []) do
    o = S.opts(opts, [device: "cpu", precision: "f32", policy: nil])
    S.unwrap(Rlx.Native.rlx_session_new(o.device, o.precision, S.json_or_nil(o.policy)))
  end

  @doc """
  The device label.
  """
  def device(this) do
    (S.unwrap(Rlx.Native.rlx_session_device(this)) || "")
  end

  @doc """
  "f32", "f16" or "bf16".
  """
  def precision(this) do
    (S.unwrap(Rlx.Native.rlx_session_precision(this)) || "")
  end

  @doc """
  The precision policy's label, if any.
  """
  def policy(this) do
    S.unwrap(Rlx.Native.rlx_session_policy(this))
  end

  @doc """
  Compile `graph` (consumed). options: {fusion, kernel_dispatch, policy}.
  """
  def compile(this, graph, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.unwrap(Rlx.Native.rlx_session_compile(this, graph, S.json_or_nil(o.options)))
  end
end

defmodule Rlx.FlexibleSession do
  @moduledoc """
  A session that picks the device per graph, by policy.
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_flexible_session_free(this)

  @doc """
  `policy`: {only, deny, prefer, benchmark_runs}.
  """
  def new(opts \\ []) do
    o = S.opts(opts, [policy: nil])
    S.unwrap(Rlx.Native.rlx_flexible_session_new(S.json_or_nil(o.policy)))
  end

  @doc """
  The policy from RLX_DEVICE / RLX_DEVICE_DENY / … environment variables.
  """
  def from_env() do
