defmodule Rlx.Runner do
  @moduledoc """
  One graph compiled for every device a policy allows, for benchmarking and picking.
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_runner_free(this)

  @doc """
  Takes `graph` (consumed); `policy`: {only, deny, prefer, benchmark_runs}.
  """
  def new(graph, opts \\ []) do
    o = S.opts(opts, [policy: nil])
    S.unwrap(Rlx.Native.rlx_runner_new(graph, S.json_or_nil(o.policy)))
  end

  @doc """
  A runner with the policy from the environment.
  """
  def from_env(graph) do
    S.unwrap(Rlx.Native.rlx_runner_from_env(graph))
  end

  @doc """
  Devices the policy allows, in preference order.
  """
  def devices(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_runner_devices(this)))
  end

  @doc """
  The fastest device by static rank.
  """
  def fastest(this) do
    (S.unwrap(Rlx.Native.rlx_runner_fastest(this)) || "")
  end

  @doc """
  The device a run with `hint` would use.
  """
  def resolve(this, opts \\ []) do
    o = S.opts(opts, [hint: nil])
    (S.unwrap(Rlx.Native.rlx_runner_resolve(this, o.hint)) || "")
  end

  @doc """
  Candidates: [{device, available, supports_graph, recommended, blocker}].
  """
  def report(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_runner_report(this)))
  end

  @doc """
  Set one f32 parameter on every device.
  """
  def set_param(this, name, data) do
    S.unwrap(Rlx.Native.rlx_runner_set_param(this, name, data, length(data)))
    :ok
  end

  @doc """
  Set several f32 parameters; returns how many.
  """
  def set_params(this, params) do
    in_params = S.inputs(params)
    S.unwrap(Rlx.Native.rlx_runner_set_params(this, in_params.names, in_params.data, in_params.lens, length(in_params.names)))
  end

  @doc """
  Set one parameter from raw bytes of `dtype`.
  """
  def set_param_typed(this, name, data, dtype) do
    S.unwrap(Rlx.Native.rlx_runner_set_param_typed(this, name, data, byte_size(data), dtype))
    :ok
  end

  @doc """
  Compile for every device now; returns the ones that compiled.
  """
  def warm_all(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_runner_warm_all(this)))
  end

  @doc """
  Time `runs` runs per device: [{device, mean_ms, …}].
  """
  def benchmark(this, inputs, opts \\ []) do
    o = S.opts(opts, [runs: 5])
    in_inputs = S.inputs(inputs)
    S.decode(S.unwrap(Rlx.Native.rlx_runner_benchmark(this, in_inputs.names, in_inputs.data, in_inputs.lens, length(in_inputs.names), o.runs)))
  end

  @doc """
  Run on the resolved device (or `hint`).
  """
  def run(this, inputs, opts \\ []) do
    o = S.opts(opts, [hint: nil])
    in_inputs = S.inputs(inputs)
    {r0, r1} = S.unwrap(Rlx.Native.rlx_runner_run(this, in_inputs.names, in_inputs.data, in_inputs.lens, length(in_inputs.names), o.hint))
    %{device: (r0 || ""), outputs: r1}
  end

  @doc """
  Run on exactly `device`.
  """
  def run_on(this, device, inputs) do
    in_inputs = S.inputs(inputs)
    S.unwrap(Rlx.Native.rlx_runner_run_on(this, device, in_inputs.names, in_inputs.data, in_inputs.lens, length(in_inputs.names)))
  end

  @doc """
  Try each device of `chain` in order until one runs.
  """
  def run_try(this, chain, inputs) do
    in_inputs = S.inputs(inputs)
    {r0, r1} = S.unwrap(Rlx.Native.rlx_runner_run_try(this, chain, length(chain), in_inputs.names, in_inputs.data, in_inputs.lens, length(in_inputs.names)))
    %{device: (r0 || ""), outputs: r1}
  end

  @doc """
  Run on `hint`, falling back down the policy when a device fails.
  """
  def run_chain(this, inputs, opts \\ []) do
    o = S.opts(opts, [hint: nil])
    in_inputs = S.inputs(inputs)
    {r0, r1} = S.unwrap(Rlx.Native.rlx_runner_run_chain(this, in_inputs.names, in_inputs.data, in_inputs.lens, length(in_inputs.names), o.hint))
    %{device: (r0 || ""), outputs: r1}
  end

  @doc """
  Resolve with the inputs in hand (shape-aware), then run.
  """
  def run_with_inputs(this, inputs, opts \\ []) do
    o = S.opts(opts, [hint: nil])
    in_inputs = S.inputs(inputs)
    S.unwrap(Rlx.Native.rlx_runner_run_with_inputs(this, in_inputs.names, in_inputs.data, in_inputs.lens, length(in_inputs.names), o.hint))
  end
end

