  Trains a graph's parameters: forward, backward, optimizer, on one device.
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_trainer_free(this)

  @doc """
  Takes `graph` (consumed): its first output is the loss. `wrt` are the
  trainable params; `initial` their starting values. options: {optimizer,
  device, resident, clip_norm, …}.
  """
  def new(graph, wrt, initial, opts \\ []) do
    o = S.opts(opts, [options: nil])
    in_initial = S.inputs(initial)
    S.unwrap(Rlx.Native.rlx_trainer_new(graph, wrt, length(wrt), in_initial.names, in_initial.data, in_initial.lens, length(in_initial.names), S.json_or_nil(o.options)))
  end

  @doc """
  One optimizer step on a batch; returns the loss.
  """
  def step(this, batch) do
    in_batch = S.inputs(batch)
    S.unwrap(Rlx.Native.rlx_trainer_step(this, in_batch.names, in_batch.data, in_batch.lens, length(in_batch.names)))
  end

  @doc """
  The loss on a batch, no update.
