  def evaluate(this, batch) do
    in_batch = S.inputs(batch)
    S.unwrap(Rlx.Native.rlx_trainer_evaluate(this, in_batch.names, in_batch.data, in_batch.lens, length(in_batch.names)))
  end

  @doc """
  Train `steps` steps, pulling batches from a callback; returns a summary.
  """
  defdelegate run(this, steps, batch, opts \\ []), to: Rlx.Manual, as: :trainer_run

  @doc """
  Stop updating `names` (all when omitted); returns how many are frozen.
  """
  def freeze(this, opts \\ []) do
    o = S.opts(opts, [names: nil])
    S.unwrap(Rlx.Native.rlx_trainer_freeze(this, (o.names || []), length(o.names || [])))
  end

  @doc """
  Resume updating `names` (all when omitted); returns how many are frozen.
  """
  def unfreeze(this, opts \\ []) do
    o = S.opts(opts, [names: nil])
    S.unwrap(Rlx.Native.rlx_trainer_unfreeze(this, (o.names || []), length(o.names || [])))
  end

  @doc """
  Frozen parameter names.
  """
  def frozen(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_trainer_frozen(this)))
  end

  @doc """
  Trainable parameter names.
  """
  def trainable(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_trainer_trainable(this)))
  end

  @doc """
