    S.unwrap(Rlx.Native.rlx_trainer_is_resident(this))
  end

  @doc """
  The current parameters.
  """
  def params(this) do
    S.unwrap(Rlx.Native.rlx_trainer_params(this))
  end

  @doc """
  Replace parameters by name; returns how many matched.
  """
  def set_params(this, params) do
    in_params = S.inputs(params)
    S.unwrap(Rlx.Native.rlx_trainer_set_params(this, in_params.names, in_params.data, in_params.lens, length(in_params.names)))
  end

  @doc """
  Change the learning rate.
  """
  def set_lr(this, lr) do
    S.unwrap(Rlx.Native.rlx_trainer_set_lr(this, lr))
    :ok
  end

  @doc """
  Steps taken.
  """
  def steps(this) do
    S.unwrap(Rlx.Native.rlx_trainer_steps(this))
  end

  @doc """
  The device it trains on.
  """
  def device(this) do
    (S.unwrap(Rlx.Native.rlx_trainer_device(this)) || "")
  end

  @doc """
  Checkpoint parameters + optimizer state as GGUF; returns tensors written.
  """
  def save(this, path) do
    S.unwrap(Rlx.Native.rlx_trainer_save(this, path))
  end

  @doc """
