  end

  @doc """
  Clear the history; reseed when `seed` is given.
  """
  def reset(this, opts \\ []) do
    o = S.opts(opts, [seed: nil])
    S.unwrap(Rlx.Native.rlx_sampler_reset(this, S.box(o.seed)))
    :ok
  end

  @doc """
  Tokens recorded so far.
  """
  def history(this) do
    S.unwrap(Rlx.Native.rlx_sampler_history(this))
  end
end

defmodule Rlx.Group do
  @moduledoc """
  This process's place in a mesh of rlx nodes: point-to-point messages,
  collectives, and the ship-graph protocol (a coordinator ships a stage or a
  training job; generic workers run it on their own hardware).
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_group_free(this)

  @doc """
  Join a mesh as `rank` of `world`. options: {peers: ["host:port", …],
  topology: "mesh" | "star", device: "auto", discover: {port, data_port,
  via}, heap_mb}. Blocks until every peer connects.
  """
  def connect(rank, world, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.unwrap(Rlx.Native.rlx_group_connect(rank, world, S.json_or_nil(o.options)))
  end

  @doc """
  Join with RANK / WORLD / PEERS / TOPOLOGY / DEVICE / DISCOVER from the environment.
  """
  def from_env() do
    S.unwrap(Rlx.Native.rlx_group_from_env())
  end

  @doc """
  This node's rank.
  """
  def rank(this) do
    S.unwrap(Rlx.Native.rlx_group_rank(this))
  end

  @doc """
  Ranks in the mesh.
  """
  def world(this) do
    S.unwrap(Rlx.Native.rlx_group_world(this))
  end

  @doc """
  Whether this is rank 0.
  """
  def is_leader(this) do
    S.unwrap(Rlx.Native.rlx_group_is_leader(this))
  end

  @doc """
  Wait until every rank arrives.
  """
  def barrier(this) do
    S.unwrap(Rlx.Native.rlx_group_barrier(this))
    :ok
  end

  @doc """
  Send f32 values to rank `to` under `tag`.
  """
  def send_(this, to, tag, data) do
    S.unwrap(Rlx.Native.rlx_group_send(this, to, tag, data, length(data)))
    :ok
  end

  @doc """
  Receive f32 values from rank `from` under `tag`.
  """
  def recv(this, from, tag) do
    S.unwrap(Rlx.Native.rlx_group_recv(this, from, tag))
  end

  @doc """
  Reduce across every rank: op "sum" | "mean" | "max" | "min".
  """
  def all_reduce(this, data, opts \\ []) do
    o = S.opts(opts, [op: "sum"])
    S.unwrap(Rlx.Native.rlx_group_all_reduce(this, data, length(data), o.op))
  end

  @doc """
  Every rank's values, concatenated in rank order.
  """
  def all_gather(this, data) do
    S.unwrap(Rlx.Native.rlx_group_all_gather(this, data, length(data)))
  end

  @doc """
  Rank `root`'s values, on every rank; other ranks pass a buffer of the root's length.
  """
  def broadcast(this, root, data) do
    S.unwrap(Rlx.Native.rlx_group_broadcast(this, root, data, length(data)))
  end

  @doc """
  Coordinator: the capabilities each worker announced, [{rank, devices, platform, role}].
  """
  def collect_caps(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_group_collect_caps(this)))
  end

  @doc """
  Coordinator: ship a stage of `graph` to worker `rank`. options: {input,
  output, device, weights: {param: uri}, packed: {param: uri}, stage_id}.
  """
  def ship_stage(this, rank, graph, options) do
    S.unwrap(Rlx.Native.rlx_group_ship_stage(this, rank, graph, S.json(options)))
    :ok
  end

  @doc """
  Send an activation to rank `to`.
  """
  def send_activation(this, to, data) do
    S.unwrap(Rlx.Native.rlx_group_send_activation(this, to, data, length(data)))
    :ok
  end

  @doc """
  Receive an activation from rank `from`.
  """
  def recv_activation(this, from) do
    S.unwrap(Rlx.Native.rlx_group_recv_activation(this, from))
  end

  @doc """
  Worker: announce, receive a stage, serve activations until the
  coordinator finishes (or `steps`). options: {steps}. Returns {rank, device, platform, activations}.
  """
  def serve_worker(this, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.decode(S.unwrap(Rlx.Native.rlx_group_serve_worker(this, S.json_or_nil(o.options))))
  end

  @doc """
  Coordinator: ship a data-parallel training job for backward `graph` to
  worker `rank`. spec: {params: [{name, uri}], data: [{input, uri, elem,
  shard_start, shard_len}], grad_start, loss_index, seed_input, momentum,
  lr_per_epoch, batch, device, push_data}.
  """
  def ship_train(this, rank, graph, spec) do
    S.unwrap(Rlx.Native.rlx_group_ship_train(this, rank, graph, S.json(spec)))
    :ok
  end

  @doc """
  Train this rank's shard of a job in lockstep with the workers; returns
  {metrics, params}.
  """
  def run_train(this, graph, spec) do
    S.decode(S.unwrap(Rlx.Native.rlx_group_run_train(this, graph, S.json(spec))))
  end

  @doc """
  Worker: announce, receive a training job, train in lockstep; returns {rank, platform, metrics, params}.
  """
  def serve_trainer(this, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.decode(S.unwrap(Rlx.Native.rlx_group_serve_trainer(this, S.json_or_nil(o.options))))
  end
end

defmodule Rlx.Model do
  @moduledoc """
  A model from any provider — an .rlxp package, a plugin's family runner
  (LLMs, speech, vision, …) — opened by path or id and run by name.
  """
  alias Rlx.Support, as: S

  @doc "Free the handle now (it is unusable afterwards)."
  def close(this), do: Rlx.Native.rlx_model_free(this)

  @doc """
  Open `source` (a path or id). options: {device, provider, …the provider's own}.
  """
  def open(source, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.unwrap(Rlx.Native.rlx_model_open(source, S.json_or_nil(o.options)))
  end

  @doc """
  {provider, family, task, device, inputs: [{name, dtype, shape}], outputs, metadata}.
  """
  def info(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_model_info(this)))
  end

  @doc """
  The task: "graph", "text-generation", "speech-recognition", ….
  """
  def task(this) do
    (S.unwrap(Rlx.Native.rlx_model_task(this)) || "")
  end

  @doc """
  f32 tensors in, f32 tensors out. options: {shapes: {name: dims}, …the model's own}.
  """
  def run(this, inputs, opts \\ []) do
    o = S.opts(opts, [options: nil])
    in_inputs = S.inputs(inputs)
    S.unwrap(Rlx.Native.rlx_model_run(this, in_inputs.names, in_inputs.data, in_inputs.lens, length(in_inputs.names), S.json_or_nil(o.options)))
  end

  @doc """
  Tensors of any dtype in (bytes + dtype), out the same way.
  """
  def run_typed(this, inputs, opts \\ []) do
    o = S.opts(opts, [options: nil])
    in_inputs = S.typed_inputs(inputs)
    S.unwrap(Rlx.Native.rlx_model_run_typed(this, in_inputs.names, in_inputs.data, in_inputs.lens, in_inputs.dtypes, length(in_inputs.names), S.json_or_nil(o.options)))
  end

  @doc """
  Dims of each output of the last run.
  """
  def output_shapes(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_model_output_shapes(this)))
  end

  @doc """
  Names of the outputs of the last run.
  """
  def output_names(this) do
    S.decode(S.unwrap(Rlx.Native.rlx_model_output_names(this)))
  end

  @doc """
  A language model's last-position logits after `ids`.
  """
  def predict_logits(this, ids) do
    S.unwrap(Rlx.Native.rlx_model_predict_logits(this, ids, length(ids)))
  end

  @doc """
  A language model's next ids after `ids`. options: {temperature, top_p, top_k, seed, stop_ids}.
  """
  def generate(this, ids, opts \\ []) do
    o = S.opts(opts, [max_tokens: 16, options: nil])
    S.unwrap(Rlx.Native.rlx_model_generate(this, ids, length(ids), o.max_tokens, S.json_or_nil(o.options)))
  end

  @doc """
  Text in, text out, for a model with a tokenizer. options: {max_tokens, temperature, …}.
  """
  def generate_text(this, prompt, opts \\ []) do
    o = S.opts(opts, [options: nil])
    (S.unwrap(Rlx.Native.rlx_model_generate_text(this, prompt, S.json_or_nil(o.options))) || "")
  end

  @doc """
  A reply to `messages` ([{role, content}, …], or one string), with the
  model's chat template applied. options: as generate_text.
  """
  def chat(this, messages, opts \\ []) do
    o = S.opts(opts, [options: nil])
    (S.unwrap(Rlx.Native.rlx_model_chat(this, S.json(messages), S.json_or_nil(o.options))) || "")
  end

  @doc """
  The text of mono `audio` at `sample_rate`, for a speech-recognition model.
  """
  def transcribe(this, audio, opts \\ []) do
    o = S.opts(opts, [sample_rate: 16000, options: nil])
    (S.unwrap(Rlx.Native.rlx_model_transcribe(this, audio, length(audio), o.sample_rate, S.json_or_nil(o.options))) || "")
  end

  @doc """
  `text` spoken, for a text-to-speech model: mono samples and their rate.
  """
  def synthesize(this, text, opts \\ []) do
    o = S.opts(opts, [options: nil])
    {r0, r1} = S.unwrap(Rlx.Native.rlx_model_synthesize(this, text, S.json_or_nil(o.options)))
    %{audio: r0, sample_rate: r1}
  end

  @doc """
  One vector per text ([[f32, …], …]), for an embedding model.
  """
  def embed(this, texts, opts \\ []) do
    o = S.opts(opts, [options: nil])
    S.decode(S.unwrap(Rlx.Native.rlx_model_embed(this, texts, length(texts), S.json_or_nil(o.options))))
  end
end
